// Helpers for the post-processor ground truth (tests/posts_gt.test.ts): RoboDK's own posts (tests/fixtures/posts_gt/cases/<case>/<RoboDK post>/, generated by
// gen_gt.py from the same job.json) vs the studio's built-in posts. Files must match token by token: text tokens
// exactly, numbers within 1e-3; blank lines, date/time lines and "generated by" comment lines are ignored.
import { existsSync, readdirSync, readFileSync, statSync } from 'node:fs';
import path from 'node:path';
import { gunzipSync, inflateRawSync } from 'node:zlib';
import '../src/posts/index';
import { getPost, PostFile } from '../src/posts/index';
import { fromPostJob, PostJob } from '../src/posts/job';

const CASES = path.resolve(__dirname, 'fixtures/posts_gt/cases');

/** RoboDK posts whose output the studio reproduces (case-prefix filter optional). */
export const STRICT: string[] = (process.env.POSTS_GT_ONLY ?? '').split(',').filter(Boolean).length
  ? (process.env.POSTS_GT_ONLY as string).split(',')
  : ['KUKA_KRC2', 'KUKA_KRC4', 'ABB_RAPID_IRC5', 'ABB_RAPID_S4C', 'ABB_RAPID_OmniCore', 'Fanuc_R30i', 'Fanuc_RJ3', 'Motoman', 'Motoman_Cartesian', 'Universal_Robots', 'Universal_Robots_URP', 'Kawasaki', 'Comau_C5G', 'Mecademic', 'Staubli_VAL3', 'CSV', 'Doosan_Robotics', 'Techman_TMscript', 'Denso_RC8', 'Epson_RC', 'Nachi_AX_FD', 'Mitsubishi', 'Dobot_V3', 'HCR', 'JAKA', 'AUBO', 'Elite_Robots_EC_V3'];

const IGNORE = [/^COMMENT\s*=/, /^\/\/\/COMM /, /^\/\/ COMM /, /generated by/i, /using nominal kinematics/i, /\b\d{1,4}[/-]\d{1,2}[/-]\d{1,4}\b/, /\b\d{1,2}:\d{2}(:\d{2})?\b/, /RoboDK v\d/];
export function normLines(text: string): string[] {
  return text.replace(/\r\n?/g, '\n').split('\n').map((l) => l.trim()).filter((l) => l && !IGNORE.some((re) => re.test(l)));
}
const NUM = /[-+]?(?:\d+\.\d*|\.\d+|\d+)(?:[eE][-+]?\d+)?/g;
export function tokens(line: string): Array<string | number> {
  const out: Array<string | number> = [];
  let last = 0;
  for (const m of line.matchAll(NUM)) {
    const pre = line.slice(last, m.index).replace(/\s+/g, '');
    // a sign glued to a word ("A1-90") stays a number sign; "X-5" in KUKA is X then -5
    if (pre) out.push(pre);
    out.push(Number(m[0]));
    last = (m.index ?? 0) + m[0].length;
  }
  const tail = line.slice(last).replace(/\s+/g, '');
  if (tail) out.push(tail);
  return out;
}
/**
 * Deliberate deviations from RoboDK, applied to RoboDK's file before comparing (each one is a RoboDK defect):
 * Programs started on a thread in a studio control program (CompileOptions.nativeThreads; the frozen cases were compiled
 * that way): RoboDK writes the bare program name; the studio UR post uses a URScript thread.
 * Comau split parts: RoboDK closes every part with the first part's names (END R_SplitTest in SplitTest1.pdl).
 * Doosan: RoboDK writes "wait_digital_input(...):" (trailing colon, invalid DRL). Epson: a stop as "Wait -0.001".
 * Circular moves on controllers without circles (Mecademic, ...): RoboDK drops them, the studio writes the arc as linear
 * moves after a "Circular move approximated with N linear moves" comment, skipped by diffPrograms.
 */
export function fixGt(post: string, job: PostJob, text: string, file = ''): string {
  const progs = [job.program, ...(job.subprograms ?? []).map((s) => s.name)];
  // RoboDK writes a program started on a thread as a plain line (the fixture generator replays it as a call): the studio
  // UR post runs it in a real URScript thread declared before the main program
  if (post.startsWith('Universal_Robots')) {
    // per program: the sequence of calls / thread starts of each name, matched to the GT lines in order
    const progs = [{ name: job.program, events: job.events }, ...(job.subprograms ?? [])];
    const seq = new Map(progs.map((p) => [p.name, p.events.filter((e: any) => e.kind === 'thread' || e.kind === 'callProgram' || (e.kind === 'runCode' && e.isCall)).map((e: any) => ({ name: String(e.name ?? e.code), thread: e.kind === 'thread' }))]));
    const threads = [...new Set([...seq.values()].flat().filter((x) => x.thread).map((x) => x.name))];
    if (threads.length) {
      const out: string[] = [];
      let cur = job.program;
      for (const l of text.split(/\r\n?|\n/)) {
        const d = l.match(/^\s*def (\w+)\(\):/);
        if (d && seq.has(d[1])) cur = d[1];
        if (l.trim() === '# Main program:') { cur = job.program; for (const t of threads) out.push(`  thread Thread_${t}():`, `    ${t}()`, '  end'); }
        const m = l.match(/^(\s*)(\w+)\(\)\s*$/);
        const list = seq.get(cur) ?? [];
        const k = m ? list.findIndex((x) => x.name === m[2]) : -1;
        if (m && k >= 0) { const ev = list.splice(k, 1)[0]; out.push(ev.thread ? `${m[1]}thrd_${m[2]} = run Thread_${m[2]}()` : l); } else out.push(l);
      }
      text = out.join('\n');
    }
  }
  // Doosan: RoboDK ends wait_digital_input(...) with ':' (DRL syntax error)
  if (post === 'Doosan_Robotics') text = text.split(String.fromCharCode(10)).map((l) => l.replace(/(wait_digital_input[(].*[)]):/, '$1')).join(String.fromCharCode(10));
  // Epson: RoboDK writes a program stop as "Wait -0.001"
  if (post === 'Epson_RC') text = text.split('Wait -0.001').join('Pause');
  // Comau split parts: RoboDK ends every part with the FIRST part's routine / program name
  if (post === 'Comau_C5G' && job.lines_x_prog) {
    const m = file.match(/^(.*?)(\d+)\.pdl$/i);
    if (m && m[1] === job.program) text = text.split(/(?=\n)/).map((l) => (l.trim() === `END R_${m[1]}` ? l.replace(`END R_${m[1]}`, `END R_${m[1]}${m[2]}`) : l.trim() === `END ${m[1]}` ? l.replace(`END ${m[1]}`, `END ${m[1]}${m[2]}`) : l.trim() === `R_${m[1]}` ? l.replace(`R_${m[1]}`, `R_${m[1]}${m[2]}`) : l)).join('');
  }
  return text;
}

/**
 * Normalisation applied to BOTH sides: RoboDK's URP post converts flange orientations of exactly 180 deg with an
 * ill-conditioned formula (the axis of a near-pi rotation vector is numerical noise); such orientations are not compared.
 */
export function normBoth(post: string, text: string): string {
  // AUBO logic-tree items carry random UUIDs (in RoboDK's output too)
  if (post === 'AUBO') return text.replace(/"[0-9a-f]{32}"/g, '"UUID"');
  if (post !== 'Universal_Robots_URP') return text;
  return text.replace(/(outputFlangePose pose="[^,]+,[^,]+,[^,]+,)([^"]+)"/g, (m, head, rot) => {
    const r = String(rot).split(',').map(Number);
    return Math.abs(Math.hypot(r[0], r[1], r[2]) - Math.PI) < 1e-3 ? `${head} PI_ROTATION"` : m;
  });
}

/** Files the studio writes and RoboDK omits (RoboDK defect): the start / stop programs every split VAL3 library declares. */
export function allowedExtra(post: string, file: string, job?: PostJob): boolean {
  if (post === 'Staubli_VAL3' && /^Main[^/]*\/[^/]+\/(start|stop)\.pgx$/.test(file)) return true;
  // KUKA: RoboDK writes the main program's .src only; the studio also writes the sub-programs it generated with it
  const base = file.toLowerCase().replace(/\.src$/, '');
  if (post.startsWith('KUKA_') && /\.src$/i.test(file) && job?.subprograms?.some((s) => s.name.replace(/[^A-Za-z0-9_]/g, '').toLowerCase().startsWith(base))) return true;
  return false;
}

/** RoboDK files the studio does not reproduce (documented gaps): JAKA's Scratch-like .zu project and its zip (random block
 * ids), AUBO's main.xml teach-pendant tree (the executable main.aubo script is compared). */
export function notReproduced(post: string, file: string): boolean {
  return (post === 'JAKA' && /(\.zu|\.zip|variable\.vi)$/i.test(file)) || (post === 'AUBO' && /main\.xml$/i.test(file));
}

/** Studio-only circular moves for controllers without circles (RoboDK drops them): the marker comment and its N moves. */
function skipArcs(lines: string[]): string[] {
  const out: string[] = [];
  for (let i = 0; i < lines.length; i++) {
    const m = lines[i].match(/Circular move approximated with (\d+) linear moves/);
    if (m) { i += Number(m[1]); continue; }
    out.push(lines[i]);
  }
  return out;
}

/** First difference between two programs, or null when equal. */
export function diffPrograms(expected: string, actual: string, tol = 1e-3): string | null {
  const a = normLines(expected), b = skipArcs(normLines(actual));
  const n = Math.max(a.length, b.length);
  for (let i = 0; i < n; i++) {
    if (a[i] === undefined || b[i] === undefined) return `line ${i + 1}: expected "${a[i] ?? '<end>'}" got "${b[i] ?? '<end>'}"`;
    const ta = tokens(a[i]), tb = tokens(b[i]);
    // within tol inclusive (1e-9 absorbs the binary noise of a difference of exactly one unit in the 3rd decimal: a value
    // at a decimal tie prints either way depending on the last bit of the platform's cos / sin)
    const same = ta.length === tb.length && ta.every((t, k) => (typeof t === 'number' && typeof tb[k] === 'number' ? Math.abs(t - (tb[k] as number)) <= tol + 1e-9 : t === tb[k]));
    if (!same) return `line ${i + 1}: expected "${a[i]}" got "${b[i]}"`;
  }
  return null;
}

function walk(dir: string, base = dir): string[] {
  const out: string[] = [];
  for (const n of readdirSync(dir)) {
    const p = path.join(dir, n);
    if (statSync(p).isDirectory()) out.push(...walk(p, base));
    else if (!n.startsWith('_')) out.push(path.relative(base, p).replace(/\\/g, '/'));
  }
  return out.sort();
}

export interface GtCase { name: string; job: PostJob; post: string; dir: string; files: string[] }
export function cases(): GtCase[] {
  if (!existsSync(CASES)) return [];
  const out: GtCase[] = [];
  for (const c of readdirSync(CASES).sort()) {
    const jp = path.join(CASES, c, 'job.json');
    if (!existsSync(jp)) continue;
    const job = JSON.parse(readFileSync(jp, 'utf8')) as PostJob;
    for (const post of job.posts ?? []) {
      const dir = path.join(CASES, c, post);
      if (!existsSync(path.join(dir, '_result.json'))) continue;
      const res = JSON.parse(readFileSync(path.join(dir, '_result.json'), 'utf8'));
      if (!res.ok) continue;
      out.push({ name: c, job, post, dir, files: walk(dir) });
    }
  }
  return out;
}

export function generateForCase(c: { job: PostJob; post: string }): PostFile[] {
  const post = getPost(c.post);
  if (!post) throw new Error(`no studio post for RoboDK post ${c.post}`);
  return post.generate(fromPostJob(c.job), { date: new Date(2026, 9, 25, 12, 0, 0), ...(c.job.lines_x_prog ? { maxLines: c.job.lines_x_prog } : {}), headerComments: c.job.header_comments ?? false });
}


/** Entries of a zip archive (stored or deflated). */
export function unzipEntries(buf: Buffer): Map<string, Buffer> {
  const out = new Map<string, Buffer>();
  let eocd = buf.length - 22;
  while (eocd >= 0 && buf.readUInt32LE(eocd) !== 0x06054b50) eocd--;
  if (eocd < 0) return out;
  let p = buf.readUInt32LE(eocd + 16);
  const n = buf.readUInt16LE(eocd + 10);
  for (let i = 0; i < n; i++) {
    const method = buf.readUInt16LE(p + 10), csize = buf.readUInt32LE(p + 20), nlen = buf.readUInt16LE(p + 28), elen = buf.readUInt16LE(p + 30), clen = buf.readUInt16LE(p + 32), off = buf.readUInt32LE(p + 42);
    const name = buf.subarray(p + 46, p + 46 + nlen).toString('utf8');
    const lnlen = buf.readUInt16LE(off + 26), lelen = buf.readUInt16LE(off + 28);
    const data = buf.subarray(off + 30 + lnlen + lelen, off + 30 + lnlen + lelen + csize);
    if (!name.endsWith('/')) out.set(name, method === 8 ? inflateRawSync(data) : Buffer.from(data));
    p += 46 + nlen + elen + clen;
  }
  return out;
}
/** Compare gzip (decompressed text) or zip archives (same entries, token-equal contents). */
export function diffArchives(expected: Buffer, actual: Buffer, fix: (t: string) => string = (t) => t, both: (t: string) => string = (t) => t): string | null {
  if (expected[0] === 0x1f && expected[1] === 0x8b) return diffPrograms(fix(gunzipSync(expected).toString('utf8')), both(gunzipSync(actual).toString('utf8')));
  if (expected.readUInt32LE(0) === 0x04034b50) {
    const a = unzipEntries(expected), b = unzipEntries(actual);
    const na = [...a.keys()].sort().join(','), nb = [...b.keys()].sort().join(',');
    if (na !== nb) return `zip entries differ: expected ${na} got ${nb}`;
    for (const [k, v] of a) { const d = diffPrograms(fix(v.toString('utf8')), both(b.get(k)!.toString('utf8'))); if (d) return `${k}: ${d}`; }
    return null;
  }
  return expected.equals(actual) ? null : 'binary files differ';
}
